1	# Local-only helper: install missing dependencies, build, stop the old local server, and run the new build.
2	# Run from PowerShell: .\start-local-windows.ps1
3	# Old builds and conversation data are retained. No git operations are performed.
4	
5	$ErrorActionPreference = 'Stop'
6	$repoDir = $PSScriptRoot
7	
8	# Same order as @agnes/host agnesHome(): AGH_HOME, then the deprecated AGNES_HOME, then HOME\.agh,
9	# then %USERPROFILE%\.agh (os.homedir() on Windows). The data directory is passed explicitly below,
10	# so it must not name a different root than the CLI resolves for the same environment.
11	function Resolve-LocalDataDir([string]$AghHome, [string]$AgnesHome, [string]$OsHome, [string]$UserProfile) {
12	    $name = 'AGH_HOME'
13	    $root = $AghHome
14	    $data = 'data'
15	    if (-not $root -or -not $root.Trim()) { $name = 'AGNES_HOME'; $root = $AgnesHome }
16	    if (-not $root -or -not $root.Trim()) { $name = 'HOME'; $root = $OsHome; $data = '.agh\data' }
17	    if (-not $root -or -not $root.Trim()) { return [IO.Path]::Combine($UserProfile, '.agh\data') }
18	    if ($root -notmatch '^(?:[A-Za-z]:[\\/]|[\\/]{2}[^\\/]+[\\/][^\\/]+)') {
19	        throw "$name must be a fully qualified absolute path, got '$root'."
20	    }
21	    return [IO.Path]::Combine($root, $data)
22	}
23	
24	$dataDir = Resolve-LocalDataDir -AghHome $env:AGH_HOME -AgnesHome $env:AGNES_HOME -OsHome $env:HOME -UserProfile $env:USERPROFILE
25	$outputDir = Join-Path $repoDir (
26	    'packages\cli\dist\local-dev-' + (Get-Date -Format 'yyyyMMdd-HHmmssfff')
27	)
28	$entry = Join-Path $outputDir 'agnes.mjs'
29	
30	# Fail closed: only the exact launcher grammar and this repository's build outputs qualify.
31	function Test-LocalAgnesProcess($ProcessInfo, [string]$Kind) {
32	    if ($null -eq $ProcessInfo -or $ProcessInfo.Name -ne 'node.exe') { return $false }
33	    $command = $ProcessInfo.CommandLine
34	    if (-not $command -or $command -notmatch '^\s*(?:"[^"]*"|[^\s"]+)(?:\s+(?:"[^"]*"|[^\s"]+))*\s*$') { return $false }
35	    $tokens = @([regex]::Matches($command, '"([^"]*)"|([^\s"]+)') | ForEach-Object {
36	        if ($_.Groups[1].Success) { $_.Groups[1].Value } else { $_.Groups[2].Value }
37	    })
38	    if ($tokens.Count -lt 3) { return $false }
39	    try {
40	        $buildEntry = [IO.Path]::GetFullPath($tokens[1])
41	        $distRoot = [IO.Path]::GetFullPath((Join-Path $repoDir 'packages\cli\dist')) + '\'
42	        if (-not [IO.Path]::IsPathRooted($tokens[1]) -or
43	            -not $buildEntry.StartsWith($distRoot, [StringComparison]::OrdinalIgnoreCase)) { return $false }
44	        $index = 2
45	        if ($Kind -eq 'web') {
46	            if ([IO.Path]::GetFileName($buildEntry) -ne 'agnes.mjs' -or $tokens[2] -ne 'serve') { return $false }
47	            $index = 3
48	        } else {
49	            if ([IO.Path]::GetFileName($buildEntry) -ne 'daemon.mjs') { return $false }
50	        }
51	        $flags = @{}
52	        for (; $index -lt $tokens.Count; $index += 2) {
53	            $flag = $tokens[$index]
54	            if ($flag -notin @('--profile', '--workspace', '--cwd', '--data-dir', '--port', '--local-web-addr', '--local-web-origin') -or
55	                $flags.ContainsKey($flag) -or $index + 1 -ge $tokens.Count) { return $false }
56	            $flags[$flag] = $tokens[$index + 1]
57	        }
58	        $workspaceFlag = if ($Kind -eq 'web') { '--cwd' } else { '--workspace' }
59	        if ($flags['--profile'] -cne 'local-dev' -or -not $flags['--data-dir'] -or -not $flags[$workspaceFlag]) { return $false }
60	        if (-not [IO.Path]::IsPathRooted($flags['--data-dir']) -or -not [IO.Path]::IsPathRooted($flags[$workspaceFlag])) { return $false }
61	        if ([IO.Path]::GetFullPath($flags['--data-dir']).TrimEnd('\') -ne [IO.Path]::GetFullPath($dataDir).TrimEnd('\') -or
62	            [IO.Path]::GetFullPath($flags[$workspaceFlag]).TrimEnd('\') -ne [IO.Path]::GetFullPath($repoDir).TrimEnd('\')) { return $false }
63	        return ($Kind -ne 'web' -or $flags['--port'] -eq '4180')
64	    } catch { return $false }
65	}
66	
67	function Stop-VerifiedLocalProcess($Candidate, [string]$Kind) {
68	    $current = Get-CimInstance Win32_Process -Filter "ProcessId = $($Candidate.ProcessId)"
69	    if ($null -eq $current) { return }
70	    if ($current.CreationDate -ne $Candidate.CreationDate -or -not (Test-LocalAgnesProcess $current $Kind)) {
71	        throw "Process identity changed (PID $($Candidate.ProcessId)); refusing to stop it."
72	    }
73	    $handle = Get-Process -Id $current.ProcessId -ErrorAction SilentlyContinue
74	    if ($null -eq $handle) { return }
75	    # Bind termination to the process instance, not a PID that could subsequently be reused.
76	    $null = $handle.Handle
77	    if ($handle.StartTime.ToUniversalTime().Ticks -ne $current.CreationDate.ToUniversalTime().Ticks) {
78	        # CIM timestamps have microsecond precision; compare at that precision.
79	        if ([Math]::Abs(($handle.StartTime - $current.CreationDate).TotalMilliseconds) -ge 1) {
80	            throw "Process start time changed (PID $($current.ProcessId)); refusing to stop it."
81	        }
82	    }
83	    Write-Host "Stopping old Agnes $Kind (PID $($current.ProcessId))..."
84	    $handle | Stop-Process -Force
85	    if (-not $handle.WaitForExit(10000)) { throw "Old Agnes $Kind did not exit within 10 seconds." }
86	}
87	
88	Push-Location -LiteralPath $repoDir
89	try {
90	    Write-Host '[1/5] Checking local dependencies...'
91	    $tsxCommand = Join-Path $repoDir 'node_modules\.bin\tsx.cmd'
92	    if (-not (Test-Path -LiteralPath $tsxCommand -PathType Leaf)) {
93	        & pnpm install --frozen-lockfile
94	        if ($LASTEXITCODE -ne 0) {
95	            throw 'Dependency install failed. The existing server has not been stopped.'
96	        }
97	        if (-not (Test-Path -LiteralPath $tsxCommand -PathType Leaf)) {
98	            throw 'tsx is still missing after install. The existing server has not been stopped.'
99	        }
100	    }
101	
102	    Write-Host '[2/5] Building the current local code...'
103	    & pnpm --filter @agnes/cli build:local --output-dir $outputDir
104	    if ($LASTEXITCODE -ne 0) {
105	        throw 'Build failed. The existing server has not been stopped.'
106	    }
107	    if (-not (Test-Path -LiteralPath $entry -PathType Leaf)) {
108	        throw 'Build output is missing. The existing server has not been stopped.'
109	    }
110	
111	    Write-Host '[3/5] Checking the existing server on port 4180...'
112	    $listeners = @(Get-NetTCPConnection -LocalPort 4180 -State Listen -ErrorAction SilentlyContinue)
113	    $processIds = @($listeners | Select-Object -ExpandProperty OwningProcess -Unique)
114	    foreach ($processId in $processIds) {
115	        $processInfo = Get-CimInstance Win32_Process -Filter "ProcessId = $processId"
116	        if (-not (Test-LocalAgnesProcess $processInfo 'web')) {
117	            throw "Port 4180 belongs to another application (PID $processId). Nothing was stopped."
118	        }
119	    }
120	    Write-Host '[4/5] Stopping the old daemon and cleaning verified local leftovers...'
121	    & node $entry daemon stop --profile local-dev --workspace $repoDir --data-dir $dataDir
122	    if ($LASTEXITCODE -ne 0) {
123	        Write-Warning 'Normal daemon stop failed; checking for verified local leftovers.'
124	    }
125	    foreach ($kind in @('daemon', 'web')) {
126	        $candidates = @(Get-CimInstance Win32_Process -Filter "Name = 'node.exe'" | Where-Object {
127	            Test-LocalAgnesProcess $_ $kind
128	        })
129	        foreach ($candidate in $candidates) { Stop-VerifiedLocalProcess $candidate $kind }
130	    }
131	    if (@(Get-NetTCPConnection -LocalPort 4180 -State Listen -ErrorAction SilentlyContinue).Count -gt 0) {
132	        throw 'Port 4180 is still occupied. The new server was not started.'
133	    }
134	
135	    Write-Host '[5/5] Starting the new build. Keep this terminal open.'
136	    Write-Host 'Open the FULL new URL printed below. Re-running this script replaces this local instance.'
137	    & node $entry serve --port 4180 --profile local-dev --cwd $repoDir --data-dir $dataDir
138	    if ($LASTEXITCODE -ne 0) {
139	        throw 'The web server exited with an error. See the output above.'
140	    }
141	} finally {
142	    Pop-Location
143	}
